def puis(x,y):
    if y==0:
        return 1
    else:
        return x * puis(x,y-1)

def conv2_10(b):
    c=len(b)
    s=0
    for i in range(c):
        k=c-i-1
        s=s+int(b[k]*puis(2,i))
    return s

#Programme Principale
print(conv2_10('1101 '))

